style.css:
@-moz-document domain("docs.google.com") {
body, div, span, input, textarea {
    font-family: "Comic Sans MS", "Comic Neue", "Caveat", cursive !important;
    background-color: #e0f7fa !important;
    color: #004d40 !important;
  }

  .kix-appview-editor {
    background-color: #b3e5fc !important;
  }

  .docs-title-input-label-inner,
  .docs-title-input {
    font-family: "Caveat", cursive !important;
    color: #01579b !important;
  }

  .kix-cursor {
    border-left: 2px solid #0288d1 !important;
  }

  /* Optional: add a subtle border to text area */
  .kix-appview-editor-container {
    border: 3px dashed #4dd0e1;
    border-radius: 10px;
  }
}
